let mailFolder='inbox',mailPage=1,mailBusy=false;
async function renderMail(){const el=document.getElementById('mailContent');if(!el)return;try{const d=await centralDirectoryRequest('/api/mail?'+new URLSearchParams({folder:mailFolder,page:mailPage}));el.innerHTML='<div class="submenu"><button class="btn" data-mail-folder="inbox">INBOX · '+d.unread+' UNREAD</button><button class="btn" data-mail-folder="sent">SENT</button><button class="btn primary" data-mail-compose>NEW MESSAGE</button><button class="btn" data-mail-refresh>REFRESH</button></div><div class="mail-layout"><section class="panel"><div class="ph"><div class="pt">'+mailFolder.toUpperCase()+'</div></div><div class="settings-body">'+(d.messages.map(m=>'<button class="mail-item '+(!m.read_at&&mailFolder==='inbox'?'unread':'')+'" data-mail-open="'+esc(m.id)+'"><b>'+esc(m.subject)+'</b><small>'+esc(mailFolder==='sent'?m.recipient:m.sender)+' · '+new Date(m.created_at).toLocaleString()+'</small></button>').join('')||'<p>No messages.</p>')+'<div class="controls"><button class="btn" data-mail-step="-1" '+(mailPage===1?'disabled':'')+'>PREVIOUS</button><span>Page '+mailPage+'</span><button class="btn" data-mail-step="1" '+(!d.hasMore?'disabled':'')+'>NEXT</button></div></div></section><section class="panel" id="mailDetail"><div class="empty">Choose a message or write to a commander.</div></section></div>';}catch(error){el.textContent=error.message;}}
async function composeMail(reply){try{if(!document.getElementById('mailDetail'))await renderMail();const data=await centralDirectoryRequest('/api/mail?recipients=1');document.getElementById('mailDetail').innerHTML='<div class="ph"><div class="pt">COMPOSE MESSAGE</div></div><form class="mail-form" id="sendPlayerMail"><label>Recipient<select name="recipient" required><option value="">Select player</option>'+data.recipients.map(r=>'<option value="'+esc(r.id)+'" '+(reply?.sender_id===r.id?'selected':'')+'>'+esc(r.username+' · '+r.planet+' · '+r.coords)+'</option>').join('')+'</select></label><label>Subject<input name="subject" required maxlength="120" value="'+esc(reply?('Re: '+reply.subject).slice(0,120):'')+'"></label><label>Message<textarea name="body" required maxlength="20000" rows="9"></textarea></label><button class="btn primary">SEND MESSAGE</button><span class="meta" role="status" id="mailSendStatus"></span></form>';}catch(e){notify(e.message,true);}}
async function openMail(id){try{const d=await centralDirectoryRequest('/api/mail?id='+encodeURIComponent(id));await renderMail();const m=d.message;document.getElementById('mailDetail').innerHTML='<div class="ph"><div class="pt">'+esc(m.subject)+'</div></div><div class="settings-body"><b>'+esc(m.sender)+' → '+esc(m.recipient)+'</b><small>'+new Date(m.created_at).toLocaleString()+'</small></div><div class="mail-body">'+esc(m.body)+'</div>'+(mailFolder==='inbox'?'<div class="controls"><button class="btn" id="replyPlayerMail">REPLY</button></div>':'');document.getElementById('replyPlayerMail')?.addEventListener('click',()=>composeMail(m));}catch(e){notify(e.message,true);}}
document.addEventListener('submit',async e=>{if(e.target.id!=='sendPlayerMail')return;e.preventDefault();if(mailBusy)return;mailBusy=true;const form=e.target,button=form.querySelector('button'),status=form.querySelector('[role="status"]');button.disabled=true;try{await centralDirectoryRequest('/api/mail',{recipientId:form.elements.recipient.value,subject:form.elements.subject.value,body:form.elements.body.value});mailFolder='sent';mailPage=1;await renderMail();document.getElementById('mailDetail').innerHTML='<div class="mail-body" role="status">✓ Message sent successfully.</div>';notify('Message sent.');}catch(error){status.textContent=error.message;button.disabled=false;}finally{mailBusy=false;}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page==='mail')renderMail();if(b.dataset.mailFolder){mailFolder=b.dataset.mailFolder;mailPage=1;renderMail();}if(b.hasAttribute('data-mail-compose'))composeMail();if(b.dataset.mailOpen)openMail(b.dataset.mailOpen);if(b.dataset.mailStep){mailPage=Math.max(1,mailPage+Number(b.dataset.mailStep));renderMail();}if(b.hasAttribute('data-mail-refresh'))renderMail();if(b.id==='resetWorkforceButton'){state.workforce=Object.fromEntries(Object.keys(WORKFORCE_LIMITS).map(k=>[k,0]));addNews('Workforce allocation reset to 0%.','good');update();notify('Workforce reset to 0%.');}});
let diplomacyBusy=false;
async function declareAllianceDiplomacy(target,action){if(diplomacyBusy)return;diplomacyBusy=true;try{const d=await centralDirectoryRequest('/api/diplomacy',{target,action,tick:state.tick,revision:planetDirectoryRevision});state.alliance.wars=d.wars;state.alliance.warDeclarations=d.warDeclarations;await refreshAfterCentralWrite();await pollDiplomaticSignals();notify((action==='war'?'War':'Peace')+' declared. The target alliance has been notified.');}catch(e){notify(e.message,true);if(typeof syncPlanetDirectory==='function')await syncPlanetDirectory();}finally{diplomacyBusy=false;}}
async function pollDiplomaticSignals(){if(document.hidden)return;if(!state.centralPlayerId||window.isStaffWorkspace)return;const owner=state.alliance,name=owner.name;if(!name||name==='Unaffiliated')return;try{const data=await centralDirectoryRequest('/api/diplomacy');if(state.alliance!==owner||data.alliance!==name)return;state.diplomaticSignalIds=state.diplomaticSignalIds||[];let changed=false;for(const signal of [...data.signals].reverse()){if(state.diplomaticSignalIds.includes(signal.id))continue;const text=signal.source+(signal.action==='war'?' declared war against ':' declared peace with ')+signal.target+'.';addNews(text,'warn');state.news[0].category='ALLIANCE';state.news[0].at=signal.createdAt;state.news[0].tick=signal.startTick;state.news[0].diplomaticSignalId=signal.id;state.news[0].diplomacy={source:signal.source,target:signal.target,action:signal.action,bonus:signal.action==='war'?{capture:signal.captureBonus,xp:signal.xpBonus}:null,expiresAt:signal.expiresAt};state.diplomaticSignalIds.push(signal.id);changed=true;}state.diplomaticSignalIds=state.diplomaticSignalIds.slice(-500);if(changed){save();renderNews();renderRailNews();}}catch{}}
setInterval(()=>{pollDiplomaticSignals();if(document.querySelector('#page-mail.active')&&!document.getElementById('sendPlayerMail')&&!document.getElementById('replyPlayerMail'))renderMail();},30000);
setTimeout(()=>{pollDiplomaticSignals();if(location.hash==='#mail'){navigate('mail');renderMail();}},2000);
function applyCentralPopulationImpact(planet){if(typeof applyAllianceIncomeTax==='function')applyAllianceIncomeTax(planet);applyCentralGovernmentOverride(planet);state.appliedBankTrades=state.appliedBankTrades||{};for(const k of Object.keys(RES)){const total=planet.bankTradeTotal?.[k]||0,previous=state.appliedBankTrades[k]||0;if(total!==previous){state.resources[k]=Math.max(0,state.resources[k]+total-previous);state.appliedBankTrades[k]=total;}}state.appliedEarthSalvage=state.appliedEarthSalvage||{};for(const k of Object.keys(RES)){const total=planet.earthSalvageTotal?.[k]||0,previous=state.appliedEarthSalvage[k]||0;if(total>previous){state.resources[k]+=total-previous;state.appliedEarthSalvage[k]=total;addNews("Earth recovery flotilla: "+nfmt(total-previous)+" "+RES[k].label+" bonus salvage received.","good");}}state.appliedGalaxyAid=state.appliedGalaxyAid||{};for(const k of Object.keys(RES)){const total=planet.galaxyAidTotal?.[k]||0,previous=state.appliedGalaxyAid[k]||0;if(total>previous){state.resources[k]+=total-previous;state.appliedGalaxyAid[k]=total;addNews('Galaxy Fund aid: '+nfmt(total-previous)+' '+RES[k].label+' received.','good');}}const total=planet.populationTaxTotal||0,previous=state.appliedPopulationTaxTotal||0;if(total>previous){const lost=total-previous;state.population=Math.max(0,state.population-lost);state.appliedPopulationTaxTotal=total;addNews('Development levy: '+lost+' residents converted to Galaxy Fund resources.','warn');state.news[0].category='POLITICS';save();}const event=planet.populationImpact;if(!event||event.id===state.appliedPopulationImpact)return;state.appliedPopulationImpact=event.id;if(event.kind==='biodome'){state.population=planet.population??state.population;state.buildings.biodome=planet.buildings?.biodome||0;state.biodomeDamage=planet.biodomeDamage||0;}if(event.kind==='strike')planet.strikeUntilTick=event.untilTick;addNews('Civil protection report: '+event.text,'warn');state.news[0].category='COVERT_OPS';save();}
let colonySyncBusy=false,civilOperationBusy=false,colonyLastSnapshot='';
async function syncOwnedColony(force=false){if(document.hidden||window.personalResetReconcileBusy)return false;if(colonySyncBusy||window.isStaffWorkspace||!state.centralPlayerId||!planetDirectoryReady)return false;const own=state.galaxy.find(p=>p.player);if(!own)return false;const payload={resetEpoch:state.resetEpoch||0,generation:state.centralResetGeneration||0,appliedBankTrades:copy(state.appliedBankTrades||{}),appliedAllianceIncomeTax:copy(state.appliedAllianceIncomeTax||{}),allianceIncomeTicks:copy(state.allianceIncomeTicks||[]),populationIncomeTicks:copy(state.populationIncomeTicks||[]),allianceTaxEnabled:!!state.userSettings.allianceTaxEnabled,appliedEarthSalvage:copy(state.appliedEarthSalvage||{}),appliedTaxTotal:state.appliedPopulationTaxTotal||0,appliedGalaxyAid:copy(state.appliedGalaxyAid||{}),appliedImpact:state.appliedPopulationImpact||'',roundLength:state.roundLength,population:state.population,biodomeDamage:state.biodomeDamage||0,publicPopulation:state.population,publicSize:totalRoids(state.roids),publicValue:playerValue(),publicScore:playerScore(),publicXP:state.xp,publicTick:state.tick,protectionTicks:state.config.protectionTicks,buildings:copy(state.buildings),resources:copy(state.resources),research:copy(state.research),workforce:copy(state.workforce),covert:copy(covertState()),incomeReport:Object.fromEntries(Object.keys(RES).map(k=>{const raw=coreIncome()+(state.roids[k]||0)*250+(state.buildings[k+'Refinery']||0)*1100;return [k,{gross:grossIncome()[k],net:income()[k],finance:raw*(state.buildings.financeCenter||0)*.005,population:raw*populationIncomeBonus()/100,refineries:(state.buildings[k+'Refinery']||0)*1100}]})),tickerRunning:!state.config.tickerPaused&&!state.config.tickerStopped};const encoded=JSON.stringify(payload);if(!force&&encoded===colonyLastSnapshot)return true;colonySyncBusy=true;try{const result=await centralDirectoryRequest('/api/colony',payload);planetDirectoryRevision=result.revision;for(const k of ['population','biodomeDamage','publicPopulation','publicSize','publicValue','publicScore','publicXP','publicTick','buildings','resources','research','workforce','covert'])own[k]=copy(payload[k]);colonyLastSnapshot=encoded;state.populationIncomeTicks=(state.populationIncomeTicks||[]).filter(r=>r.tick>payload.publicTick);state.allianceIncomeTicks=(state.allianceIncomeTicks||[]).filter(r=>r.tick>payload.publicTick);await refreshAfterCentralWrite();if(typeof refreshGalaxyDevelopment==='function')await refreshGalaxyDevelopment();return true;}catch(error){if(error.status===409&&typeof refreshSharedPlanets==='function')await refreshSharedPlanets();return false;}finally{colonySyncBusy=false;}}
async function runCivilCovert(op,n,p){if(civilOperationBusy)return;civilOperationBusy=true;try{if(!await syncOwnedColony(true))throw Error('The colony report changed. Refresh and retry.');const result=await centralDirectoryRequest('/api/civil-covert',{operation:op[0],targetId:p.id,agents:n,generation:state.centralResetGeneration||0});planetDirectoryRevision=result.revision;state.resources=result.resources;const c=covertState(),history=c.history;Object.assign(c,result.covert);c.history=history;state.xp+=result.xp;const report={tick:state.tick,operation:op[1],coords:p.coords,agents:n,success:result.success,result:result.text+' · '+result.xp+' XP'};c.history.unshift(report);c.history=c.history.slice(0,100);addNews('Covert operation '+op[1]+' at '+p.coords+': '+report.result,result.success?'good':'warn');state.news[0].category='COVERT_OPS';await refreshAfterCentralWrite();notify(result.success?'Operation succeeded. Target colony notified.':'Operation detected.');}catch(error){notify(error.message,true);}finally{civilOperationBusy=false;}}
setInterval(()=>syncOwnedColony(),30000);
setTimeout(()=>syncOwnedColony(),3000);

async function refreshAfterCentralWrite(){clearTimeout(planetDirectoryTimer);const data=await centralDirectoryRequest('/api/planets');applySharedDirectory(data);}

// SF-096: consume each staff government command once, without changing normal revolutions.
function applyCentralGovernmentOverride(planet){const command=planet.governmentOverride;if(!command||command.id===state.appliedGovernmentOverride||(command.resetEpoch||0)!==(state.resetEpoch||0)||!['None','Corporatism','Democracy','Nationalism','Socialism','Totalitarianism'].includes(command.government))return false;state.government=command.government;state.governmentPending=null;state.governmentRevolutionUntil=0;state.appliedGovernmentOverride=command.id;save();return true;}
